// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.TicketRollup.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(ticketrollup.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *TicketRollupUpsertOne) UpdateNewValues() *TicketRollupUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(ticketrollup.FieldID)
		}
		if _, exists := u.create.mutation.TenantID(); exists {
			s.SetIgnore(ticketrollup.FieldTenantID)
		}
		if _, exists := u.create.mutation.Granularity(); exists {
			s.SetIgnore(ticketrollup.FieldGranularity)
		}
		if _, exists := u.create.mutation.BucketStart(); exists {
			s.SetIgnore(ticketrollup.FieldBucketStart)
		}
		if _, exists := u.create.mutation.TeamID(); exists {
			s.SetIgnore(ticketrollup.FieldTeamID)
		}
		if _, exists := u.create.mutation.AgentID(); exists {
			s.SetIgnore(ticketrollup.FieldAgentID)
		}
		if _, exists := u.create.mutation.CategoryID(); exists {
			s.SetIgnore(ticketrollup.FieldCategoryID)
		}
		if _, exists := u.create.mutation.Channel(); exists {
			s.SetIgnore(ticketrollup.FieldChannel)
		}
		if _, exists := u.create.mutation.Priority(); exists {
			s.SetIgnore(ticketrollup.FieldPriority)
		}
	}))
	return u
}

