// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.TicketRollup.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(ticketrollup.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *TicketRollupUpsertBulk) UpdateNewValues() *TicketRollupUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(ticketrollup.FieldID)
			}
			if _, exists := b.mutation.TenantID(); exists {
				s.SetIgnore(ticketrollup.FieldTenantID)
			}
			if _, exists := b.mutation.Granularity(); exists {
				s.SetIgnore(ticketrollup.FieldGranularity)
			}
			if _, exists := b.mutation.BucketStart(); exists {
				s.SetIgnore(ticketrollup.FieldBucketStart)
			}
			if _, exists := b.mutation.TeamID(); exists {
				s.SetIgnore(ticketrollup.FieldTeamID)
			}
			if _, exists := b.mutation.AgentID(); exists {
				s.SetIgnore(ticketrollup.FieldAgentID)
			}
			if _, exists := b.mutation.CategoryID(); exists {
				s.SetIgnore(ticketrollup.FieldCategoryID)
			}
			if _, exists := b.mutation.Channel(); exists {
				s.SetIgnore(ticketrollup.FieldChannel)
			}
			if _, exists := b.mutation.Priority(); exists {
				s.SetIgnore(ticketrollup.FieldPriority)
			}
		}
	}))
	return u
}

